public class Main {
    public static void main(String[] args) {
        int[][] cost = {{9, 2, 7, 8}, {6, 4, 3, 7}, {5, 8, 1, 8}, {7, 6, 9, 4}};
        int n = cost.length, full = (1 << n) - 1, INF = 1000000000;
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder("worker " + i + " costs:");
            for (int c : cost[i]) sb.append(" ").append(c);
            System.out.println(sb);
        }
        int[] dp = new int[1 << n];    // dp[mask] = cheapest way to hand out the jobs in mask
        int[] last = new int[1 << n];  // last[mask] = job handed out most recently
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            int w = Integer.bitCount(mask);          // the next worker is the number of jobs taken
            for (int j = 0; j < n; j++) {
                if ((mask >> j & 1) == 1) continue;  // job j is already taken
                int nm = mask | (1 << j);
                if (dp[mask] + cost[w][j] < dp[nm]) { dp[nm] = dp[mask] + cost[w][j]; last[nm] = j; }
            }
        }
        System.out.println("Minimum total cost = " + dp[full]);
        int[] job = new int[n];
        for (int mask = full; mask != 0; mask ^= 1 << last[mask])  // walk back through the choices
            job[Integer.bitCount(mask) - 1] = last[mask];
        for (int i = 0; i < n; i++)
            System.out.println("worker " + i + " -> job " + job[i] + " (cost " + cost[i][job[i]] + ")");
        // Time O(2^n * n), space O(2^n)
    }
}

