using System;

class Program {
    static int BitCount(int x) { int c = 0; while (x != 0) { c += x & 1; x >>= 1; } return c; }

    static void Main() {
        int[][] cost = { new[] {9, 2, 7, 8}, new[] {6, 4, 3, 7}, new[] {5, 8, 1, 8}, new[] {7, 6, 9, 4} };
        int n = cost.Length, full = (1 << n) - 1, INF = 1000000000;
        for (int i = 0; i < n; i++)
            Console.WriteLine("worker " + i + " costs: " + string.Join(" ", cost[i]));
        int[] dp = new int[1 << n];    // dp[mask] = cheapest way to hand out the jobs in mask
        int[] last = new int[1 << n];  // last[mask] = job handed out most recently
        for (int m = 0; m <= full; m++) dp[m] = INF;
        dp[0] = 0;
        for (int mask = 0; mask < full; mask++) {
            int w = BitCount(mask);                  // the next worker is the number of jobs taken
            for (int j = 0; j < n; j++) {
                if ((mask >> j & 1) == 1) continue;  // job j is already taken
                int nm = mask | (1 << j);
                if (dp[mask] + cost[w][j] < dp[nm]) { dp[nm] = dp[mask] + cost[w][j]; last[nm] = j; }
            }
        }
        Console.WriteLine("Minimum total cost = " + dp[full]);
        int[] job = new int[n];
        for (int mask = full; mask != 0; mask ^= 1 << last[mask])  // walk back through the choices
            job[BitCount(mask) - 1] = last[mask];
        for (int i = 0; i < n; i++)
            Console.WriteLine("worker " + i + " -> job " + job[i] + " (cost " + cost[i][job[i]] + ")");
        // Time O(2^n * n), space O(2^n)
    }
}

