public class Main {
    public static void main(String[] args) {
        int[][] d = {{0, 10, 15, 20}, {10, 0, 35, 25}, {15, 35, 0, 30}, {20, 25, 30, 0}};
        int n = d.length, full = (1 << n) - 1, INF = 1000000000;
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder("from city " + i + ":");
            for (int x : d[i]) sb.append(" ").append(x);
            System.out.println(sb);
        }
        // dp[mask][v] = cheapest path that starts at city 0, visits exactly mask, ends at v
        int[][] dp = new int[1 << n][n];
        for (int[] row : dp) java.util.Arrays.fill(row, INF);
        dp[1][0] = 0;                                    // only city 0 visited, standing on it
        for (int mask = 1; mask <= full; mask++) {
            for (int v = 0; v < n; v++) {
                if (dp[mask][v] == INF) continue;
                for (int u = 0; u < n; u++) {            // extend the path by one unvisited city
                    if ((mask >> u & 1) == 1) continue;
                    int nm = mask | (1 << u);
                    dp[nm][u] = Math.min(dp[nm][u], dp[mask][v] + d[v][u]);
                }
            }
        }
        int best = INF;
        for (int v = 1; v < n; v++)                      // close the tour back to city 0
            best = Math.min(best, dp[full][v] + d[v][0]);
        System.out.println("States = " + (1 << n) * n + ", shortest tour = " + best);
        // Time O(2^n * n^2), space O(2^n * n)
    }
}

