public class Main {
    static int[] digs;
    static long[][][] memo;

    // tight: all digits so far equal N's digits. started: a non-zero digit was already placed.
    static long go(int pos, int mask, boolean tight, boolean started) {
        if (pos == digs.length) return 1;                 // one valid number was built
        int st = started ? 1 : 0;
        if (!tight && memo[pos][mask][st] >= 0) return memo[pos][mask][st];
        int limit = tight ? digs[pos] : 9;                // tight caps the digit at N's digit
        long res = 0;
        for (int d = 0; d <= limit; d++) {
            boolean ns = started || d > 0;                // leading zeros are not real digits
            if (ns && (mask >> d & 1) == 1) continue;     // digit d was used before
            res += go(pos + 1, ns ? mask | (1 << d) : mask, tight && d == limit, ns);
        }
        if (!tight) memo[pos][mask][st] = res;            // only free states are reused
        return res;
    }

    static long count(long n) {
        String s = Long.toString(n);
        digs = new int[s.length()];
        for (int i = 0; i < s.length(); i++) digs[i] = s.charAt(i) - '0';
        memo = new long[s.length()][1024][2];
        for (long[][] a : memo) for (long[] b : a) java.util.Arrays.fill(b, -1);
        return go(0, 0, true, false);
    }

    static boolean distinct(int x) {
        int mask = 0;
        for (; x > 0; x /= 10) { if ((mask >> (x % 10) & 1) == 1) return false; mask |= 1 << (x % 10); }
        return true;
    }

    public static void main(String[] args) {
        for (int n : new int[]{20, 100, 1000, 54321}) {
            int brute = 0;
            for (int x = 0; x <= n; x++) if (distinct(x)) brute++;
            System.out.println("N = " + n + ": digit DP = " + count(n) + ", brute force = " + brute);
        }
        // Time O(digits * 2^10 * 10), space O(digits * 2^10)
    }
}

