    memo = {}

    # tight: all digits so far equal N's digits. started: a non-zero digit was already placed.
    def go(pos, mask, tight, started):
        if pos == len(digs):
            return 1                                  # one valid number was built
        key = (pos, mask, started)
        if not tight and key in memo:
            return memo[key]
        limit = digs[pos] if tight else 9             # tight caps the digit at N's digit
        res = 0
        for d in range(limit + 1):
            ns = started or d > 0                     # leading zeros are not real digits
            if ns and mask >> d & 1:                  # digit d was used before
                continue
            res += go(pos + 1, mask | (1 << d) if ns else mask, tight and d == limit, ns)
        if not tight:
            memo[key] = res                           # only free states are reused
        return res

    return go(0, 0, True, False)

def distinct(x):
