function count(n) {
  const digs = String(n).split("").map(Number);
  const memo = new Map();

  // tight: all digits so far equal N's digits. started: a non-zero digit was already placed.
  function go(pos, mask, tight, started) {
    if (pos === digs.length) return 1;               // one valid number was built
    const key = (pos * 1024 + mask) * 2 + (started ? 1 : 0);
    if (!tight && memo.has(key)) return memo.get(key);
    const limit = tight ? digs[pos] : 9;             // tight caps the digit at N's digit
    let res = 0;
    for (let d = 0; d <= limit; d++) {
      const ns = started || d > 0;                   // leading zeros are not real digits
      if (ns && (mask >> d & 1)) continue;           // digit d was used before
      res += go(pos + 1, ns ? mask | (1 << d) : mask, tight && d === limit, ns);
    }
    if (!tight) memo.set(key, res);                  // only free states are reused
    return res;
  }
  return go(0, 0, true, false);
}

function distinct(x) {
  const s = String(x);
  return new Set(s).size === s.length;
}

for (const n of [20, 100, 1000, 54321]) {
  let brute = 0;
  for (let x = 0; x <= n; x++) if (distinct(x)) brute++;
  console.log("N = " + n + ": digit DP = " + count(n) + ", brute force = " + brute);
}
// Time O(digits * 2^10 * 10), space O(digits * 2^10)

