#include <bits/stdc++.h>
using namespace std;

vector<int> digs;
long long memo[20][1024][2];

// tight: all digits so far equal N's digits. started: a non-zero digit was already placed.
long long go(int pos, int mask, bool tight, bool started) {
    if (pos == (int)digs.size()) return 1;             // one valid number was built
    if (!tight && memo[pos][mask][started] >= 0) return memo[pos][mask][started];
    int limit = tight ? digs[pos] : 9;                 // tight caps the digit at N's digit
    long long res = 0;
    for (int d = 0; d <= limit; d++) {
        bool ns = started || d > 0;                    // leading zeros are not real digits
        if (ns && (mask >> d & 1)) continue;           // digit d was used before
        res += go(pos + 1, ns ? mask | (1 << d) : mask, tight && d == limit, ns);
    }
    if (!tight) memo[pos][mask][started] = res;        // only free states are reused
    return res;
}

long long countUpTo(long long n) {
    string s = to_string(n);
    digs.clear();
    for (char c : s) digs.push_back(c - '0');
    memset(memo, -1, sizeof(memo));
    return go(0, 0, true, false);
}

bool distinctDigits(int x) {
    int mask = 0;
    for (; x > 0; x /= 10) { if (mask >> (x % 10) & 1) return false; mask |= 1 << (x % 10); }
    return true;
}

int main() {
    for (int n : {20, 100, 1000, 54321}) {
        int brute = 0;
        for (int x = 0; x <= n; x++) if (distinctDigits(x)) brute++;
        cout << "N = " << n << ": digit DP = " << countUpTo(n) << ", brute force = " << brute << "\n";
    }
    // Time O(digits * 2^10 * 10), space O(digits * 2^10)
    return 0;
}

