public class Main {
    static final int LEN = 18;
    static long[][] ways;   // ways[len][s] = digit strings of this length (zeros allowed) with sum s

    static String kth(long k, int S) {
        int len = 1;
        while (true) {                          // step 1: find how many digits the answer has
            long cnt = 0;
            for (int d = 1; d <= 9 && d <= S; d++) cnt += ways[len - 1][S - d];
            if (k <= cnt) break;
            k -= cnt;                           // skip every number of this length
            len++;
        }
        StringBuilder sb = new StringBuilder();
        int rem = S;
        for (int pos = 0; pos < len; pos++) {   // step 2: fix the digits from left to right
            for (int d = (pos == 0 ? 1 : 0); d <= 9 && d <= rem; d++) {
                long c = ways[len - pos - 1][rem - d];   // numbers that start with this prefix
                if (k <= c) { sb.append(d); rem -= d; break; }
                k -= c;                         // the answer is not under digit d
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int S = 10;
        ways = new long[LEN + 1][S + 1];
        ways[0][0] = 1;
        for (int len = 1; len <= LEN; len++)
            for (int s = 0; s <= S; s++)
                for (int d = 0; d <= 9 && d <= s; d++) ways[len][s] += ways[len - 1][s - d];
        for (int k : new int[]{1, 5, 9, 10, 20, 100, 1000})
            System.out.println("S = " + S + ", K = " + k + " -> " + kth(k, S));
        // Time O(digits * 10) per query after an O(digits * S * 10) table; space O(digits * S)
    }
}

