    int len = 1;
    while (true) {                            // step 1: find how many digits the answer has
        long long cnt = 0;
        for (int d = 1; d <= 9 && d <= S; d++) cnt += ways[len - 1][S - d];
        if (k <= cnt) break;
        k -= cnt;                             // skip every number of this length
        len++;
    }
    string out;
    int rem = S;
    for (int pos = 0; pos < len; pos++) {     // step 2: fix the digits from left to right
        for (int d = (pos == 0 ? 1 : 0); d <= 9 && d <= rem; d++) {
            long long c = ways[len - pos - 1][rem - d];   // numbers that start with this prefix
            if (k <= c) { out += char('0' + d); rem -= d; break; }
            k -= c;                           // the answer is not under digit d
        }
    }
    return out;
}

int main() {
    int S = 10;
    ways[0][0] = 1;
    for (int len = 1; len <= LEN; len++)
        for (int s = 0; s <= S; s++)
            for (int d = 0; d <= 9 && d <= s; d++) ways[len][s] += ways[len - 1][s - d];
    for (int k : {1, 5, 9, 10, 20, 100, 1000})
        cout << "S = " << S << ", K = " << k << " -> " << kth(k, S) << "\n";
    // Time O(digits * 10) per query after an O(digits * S * 10) table; space O(digits * S)
    return 0;
}

