public class Main {
    public static void main(String[] args) {
        int n = 10;
        System.out.println("Walk from 0; each step is +1 or +2 with probability 1/2; target n = " + n);

        // Forward: the probability is known at the start (1 at position 0), so push it along.
        double[] p = new double[n + 2];
        p[0] = 1.0;
        for (int i = 0; i < n; i++) {
            p[i + 1] += p[i] * 0.5;
            p[i + 2] += p[i] * 0.5;
        }
        System.out.println(String.format("P(land exactly on %d) = %.4f", n, p[n]));

        // Backward: the expected remaining steps are known at the end (0 once we reach n).
        double[] e = new double[n + 2];
        for (int i = n - 1; i >= 0; i--)
            e[i] = 1 + 0.5 * e[i + 1] + 0.5 * e[i + 2];   // one step now, then the average future
        System.out.println(String.format("E(steps until position >= %d) = %.4f", n, e[0]));

        for (int i = 0; i <= n; i += 4)
            System.out.println(String.format("position %d: P(visit) = %.4f, E(steps left) = %.4f", i, p[i], e[i]));
        // Time O(n), space O(n)
    }
}

