public class Main {
    static int n;
    static long perms, fixedTotal;
    static boolean[] used;

    // Place a value at every position; 'fixed' counts positions where value == position.
    static void gen(int pos, int fixed) {
        if (pos == n) { perms++; fixedTotal += fixed; return; }
        for (int v = 0; v < n; v++) {
            if (used[v]) continue;
            used[v] = true;
            gen(pos + 1, fixed + (v == pos ? 1 : 0));
            used[v] = false;
        }
    }

    public static void main(String[] args) {
        for (n = 3; n <= 7; n++) {
            perms = 0; fixedTotal = 0;
            used = new boolean[n];
            gen(0, 0);                       // brute force: O(n!) work
            // Linearity: each of the n cards stays put with probability 1/n, so E = n * (1/n) = 1.
            System.out.println("n = " + n + ": " + perms + " permutations, " + fixedTotal
                + " fixed points in total, average = " + fixedTotal / perms + " (formula n * 1/n = 1)");
        }
        // Brute force: time O(n * n!), space O(n). Formula: O(1).
    }
}

