code.java:
public class Main {
    static int slow(int[] a, int k) {              // try every allowed j: O(N * k)
        int n = a.length;
        int[] dp = new int[n];
        dp[0] = a[0];
        for (int i = 1; i < n; i++) {
            int best = Integer.MIN_VALUE;
            for (int j = Math.max(0, i - k); j < i; j++) best = Math.max(best, dp[j]);
            dp[i] = a[i] + best;
        }
        return dp[n - 1];
    }

    static int fast(int[] a, int k) {              // same recurrence, the max comes from a deque
        int n = a.length, head = 0, tail = 0;
        int[] dp = new int[n], dq = new int[n];    // dq holds indices, their dp values decrease
        dp[0] = a[0];
        dq[tail++] = 0;
        for (int i = 1; i < n; i++) {
            if (dq[head] < i - k) head++;          // the front left the window
            dp[i] = a[i] + dp[dq[head]];           // the front is the window maximum
            while (tail > head && dp[dq[tail - 1]] <= dp[i]) tail--;  // drop values that can never win
            dq[tail++] = i;
        }
        return dp[n - 1];
    }

    public static void main(String[] args) {
        int[] a = {1, -5, -20, 4, -1, 3, -6, -3};
        int k = 2;
        StringBuilder sb = new StringBuilder("a =");
        for (int x : a) sb.append(" ").append(x);
        System.out.println(sb + ", jump at most k = " + k);
        System.out.println("O(N*k) loop: best score = " + slow(a, k));
        System.out.println("O(N) deque:  best score = " + fast(a, k));
        // Deque version: time O(N) (each index is pushed and popped once), space O(N)
    }
}

