public class Main {
    static long[] M, B;            // line j: y = M[j] * x + B[j]
    static int head = 0, size = 0;

    // With slopes decreasing, the middle line l2 is never the minimum if l3 overtakes l1 before l2 does.
    static boolean useless(int l1, int l2, long m3, long b3) {
        return (b3 - B[l1]) * (M[l1] - M[l2]) <= (B[l2] - B[l1]) * (M[l1] - m3);
    }

    static void add(long m, long b) {
        while (size - head >= 2 && useless(size - 2, size - 1, m, b)) size--;
        M[size] = m; B[size] = b; size++;
    }

    static long query(long x) {    // x only grows, so the front pointer only moves forward
        while (size - head >= 2 && M[head + 1] * x + B[head + 1] <= M[head] * x + B[head]) head++;
        return M[head] * x + B[head];
    }

    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5, 9, 2, 6};
        long C = 20;
        int n = a.length;
        long[] p = new long[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];

        long[] slow = new long[n + 1];                 // plain O(N^2) reference
        for (int i = 1; i <= n; i++) {
            slow[i] = Long.MAX_VALUE;
            for (int j = 0; j < i; j++)
                slow[i] = Math.min(slow[i], slow[j] + (p[i] - p[j]) * (p[i] - p[j]) + C);
        }

        // (p[i]-p[j])^2 = p[i]^2 - 2*p[j]*p[i] + p[j]^2  ->  line with slope -2*p[j], intercept dp[j]+p[j]^2
        M = new long[n + 1]; B = new long[n + 1];
        long[] dp = new long[n + 1];
        add(0, 0);
        for (int i = 1; i <= n; i++) {
            dp[i] = query(p[i]) + p[i] * p[i] + C;
            add(-2 * p[i], dp[i] + p[i] * p[i]);
        }
        StringBuilder sb = new StringBuilder("a =");
        for (int x : a) sb.append(" ").append(x);
        System.out.println(sb + ", cost per group = (sum)^2 + " + C);
        System.out.println("O(N^2) DP:         " + slow[n]);
        System.out.println("Convex hull trick: " + dp[n]);
        // Time O(N), space O(N)
    }
}

