    while ((int)M.size() - head >= 2 && useless(M.size() - 2, M.size() - 1, m, b)) { M.pop_back(); B.pop_back(); }
    M.push_back(m); B.push_back(b);
}

long long query(long long x) { // x only grows, so the front pointer only moves forward
    while ((int)M.size() - head >= 2 && M[head + 1] * x + B[head + 1] <= M[head] * x + B[head]) head++;
    return M[head] * x + B[head];
}

int main() {
    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};
    long long C = 20;
    int n = a.size();
    vector<long long> p(n + 1, 0);
    for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];

    vector<long long> slow(n + 1, 0);              // plain O(N^2) reference
    for (int i = 1; i <= n; i++) {
        slow[i] = LLONG_MAX;
        for (int j = 0; j < i; j++)
            slow[i] = min(slow[i], slow[j] + (p[i] - p[j]) * (p[i] - p[j]) + C);
    }

    // (p[i]-p[j])^2 = p[i]^2 - 2*p[j]*p[i] + p[j]^2  ->  line with slope -2*p[j], intercept dp[j]+p[j]^2
    vector<long long> dp(n + 1, 0);
    add(0, 0);
    for (int i = 1; i <= n; i++) {
        dp[i] = query(p[i]) + p[i] * p[i] + C;
        add(-2 * p[i], dp[i] + p[i] * p[i]);
    }
    cout << "a =";
    for (int x : a) cout << " " << x;
    cout << ", cost per group = (sum)^2 + " << C << "\n";
    cout << "O(N^2) DP:         " << slow[n] << "\n";
    cout << "Convex hull trick: " << dp[n] << "\n";
    // Time O(N), space O(N)
    return 0;
}

