public class Main {
    static final int LO = 0, HI = 15;
    static final long INF = (long) 1e18;
    static long[] M = new long[64], B = new long[64];   // one line per segment-tree node

    static void insert(int node, int lo, int hi, long m, long b) {
        int mid = (lo + hi) / 2;
        if (m * mid + b < M[node] * mid + B[node]) {     // the line that wins at mid stays here
            long tm = M[node], tb = B[node];
            M[node] = m; B[node] = b; m = tm; b = tb;
        }
        if (lo == hi) return;
        // Two lines cross at most once, so the loser can win on one side only.
        if (m * lo + b < M[node] * lo + B[node]) insert(2 * node, lo, mid, m, b);
        else if (m * hi + b < M[node] * hi + B[node]) insert(2 * node + 1, mid + 1, hi, m, b);
    }

    static long query(int x) {                           // best of the lines on the root-to-leaf path
        int node = 1, lo = LO, hi = HI;
        long best = INF;
        while (true) {
            best = Math.min(best, M[node] * x + B[node]);
            if (lo == hi) return best;
            int mid = (lo + hi) / 2;
            if (x <= mid) { node = 2 * node; hi = mid; } else { node = 2 * node + 1; lo = mid + 1; }
        }
    }

    public static void main(String[] args) {
        long[][] lines = {{3, 0}, {-2, 40}, {0, 18}, {1, 5}};
        java.util.Arrays.fill(B, INF);                   // every node starts with y = INF
        for (long[] l : lines) {
            insert(1, LO, HI, l[0], l[1]);
            System.out.println("insert y = " + l[0] + "x + " + l[1]);
        }
        for (int x : new int[]{0, 4, 8, 12, 15}) {
            long brute = INF;
            for (long[] l : lines) brute = Math.min(brute, l[0] * x + l[1]);
            System.out.println("x = " + x + ": Li Chao min = " + query(x) + ", brute force = " + brute);
        }
        // Time O(log C) per insert and per query, space O(C) for an x range of size C
    }
}

