public class Main {
    static int[] a = {2, 7, 1, 8, 2, 8};
    static long[] p;

    // kind 0: (sum of a[i..j])^2, a convex cost.  kind 1: -(length)^2, a concave cost.
    static long w(int kind, int i, int j) {
        if (kind == 0) { long s = p[j + 1] - p[i]; return s * s; }
        long len = j - i + 1;
        return -len * len;
    }

    static void check(int kind, String name) {
        int n = a.length, checks = 0, bad = 0;
        String first = "";
        for (int x = 0; x < n; x++)
            for (int y = x; y < n; y++)
                for (int c = y; c < n; c++)
                    for (int d = c; d < n; d++) {          // every x <= y <= c <= d
                        long crossing = w(kind, x, c) + w(kind, y, d);
                        long nested = w(kind, x, d) + w(kind, y, c);
                        checks++;
                        if (crossing > nested) {           // QI demands crossing <= nested
                            if (bad == 0) first = ", first: a=" + x + " b=" + y + " c=" + c + " d=" + d
                                + " gives " + crossing + " > " + nested;
                            bad++;
                        }
                    }
        System.out.println(name + ": " + bad + " violations in " + checks + " checks" + first);
    }

    public static void main(String[] args) {
        int n = a.length;
        p = new long[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];
        StringBuilder sb = new StringBuilder("a =");
        for (int v : a) sb.append(" ").append(v);
        System.out.println(sb);
        check(0, "w = (sum)^2");
        check(1, "w = -(length)^2");
        // Time O(N^4) for the full check, space O(N)
    }
}

