public class Main {
    static final long INF = (long) 1e15;
    static long[] p, prev, cur;

    static long cost(int j, int i) { long s = p[i] - p[j]; return s * s; }   // group a[j..i-1]

    // Fill cur[lo..hi]; the best split for each of them lies in [optLo, optHi].
    static void solve(int lo, int hi, int optLo, int optHi) {
        if (lo > hi) return;
        int mid = (lo + hi) / 2, bestJ = optLo;
        long best = Long.MAX_VALUE;
        for (int j = optLo; j <= Math.min(mid - 1, optHi); j++) {
            long v = prev[j] + cost(j, mid);
            if (v < best) { best = v; bestJ = j; }
        }
        cur[mid] = best;
        solve(lo, mid - 1, optLo, bestJ);     // smaller i -> split point no further right
        solve(mid + 1, hi, bestJ, optHi);     // larger i  -> split point no further left
    }

    public static void main(String[] args) {
        int[] a = {3, 1, 4, 1, 5, 9, 2, 6};
        int n = a.length, K = 3;
        p = new long[n + 1];
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];

        long[][] slow = new long[K + 1][n + 1];            // slow[k][i]: first i items in k groups
        for (long[] row : slow) java.util.Arrays.fill(row, INF);
        slow[0][0] = 0;
        for (int k = 1; k <= K; k++)
            for (int i = 1; i <= n; i++)
                for (int j = 0; j < i; j++)
                    slow[k][i] = Math.min(slow[k][i], slow[k - 1][j] + cost(j, i));

        prev = new long[n + 1];
        java.util.Arrays.fill(prev, INF);
        prev[0] = 0;
        for (int k = 1; k <= K; k++) {                     // one layer per group count
            cur = new long[n + 1];
            cur[0] = INF;
            solve(1, n, 0, n - 1);
            prev = cur;
        }
        StringBuilder sb = new StringBuilder("a =");
        for (int v : a) sb.append(" ").append(v);
        System.out.println(sb + ", K = " + K + " groups, cost of a group = (sum)^2");
        System.out.println("Plain DP O(K*N^2):       " + slow[K][n]);
        System.out.println("D&C opt O(K*N log N):    " + prev[n]);
        // Time O(K * N log N), space O(N) for the optimised version
    }
}

