const long long INF = 1000000000000000LL;
vector<long long> p, prv, cur;

long long cost(int j, int i) { long long s = p[i] - p[j]; return s * s; }   // group a[j..i-1]

// Fill cur[lo..hi]; the best split for each of them lies in [optLo, optHi].
void solve(int lo, int hi, int optLo, int optHi) {
    if (lo > hi) return;
    int mid = (lo + hi) / 2, bestJ = optLo;
    long long best = LLONG_MAX;
    for (int j = optLo; j <= min(mid - 1, optHi); j++) {
        long long v = prv[j] + cost(j, mid);
        if (v < best) { best = v; bestJ = j; }
    }
    cur[mid] = best;
    solve(lo, mid - 1, optLo, bestJ);     // smaller i -> split point no further right
    solve(mid + 1, hi, bestJ, optHi);     // larger i  -> split point no further left
}

int main() {
    vector<int> a = {3, 1, 4, 1, 5, 9, 2, 6};
    int n = a.size(), K = 3;
    p.assign(n + 1, 0);
    for (int i = 0; i < n; i++) p[i + 1] = p[i] + a[i];

    vector<vector<long long>> slow(K + 1, vector<long long>(n + 1, INF));   // first i items in k groups
    slow[0][0] = 0;
    for (int k = 1; k <= K; k++)
        for (int i = 1; i <= n; i++)
            for (int j = 0; j < i; j++)
                slow[k][i] = min(slow[k][i], slow[k - 1][j] + cost(j, i));

    prv.assign(n + 1, INF);
    prv[0] = 0;
    for (int k = 1; k <= K; k++) {        // one layer per group count
        cur.assign(n + 1, INF);
        solve(1, n, 0, n - 1);
        prv = cur;
    }
    cout << "a =";
    for (int v : a) cout << " " << v;
    cout << ", K = " << K << " groups, cost of a group = (sum)^2\n";
    cout << "Plain DP O(K*N^2):       " << slow[K][n] << "\n";
    cout << "D&C opt O(K*N log N):    " << prv[n] << "\n";
    // Time O(K * N log N), space O(N) for the optimised version
    return 0;
}

