public class Main {
    public static void main(String[] args) {
        int[] a = {1, 2, 4, 3, 5, 0, 6, 7, 2, 0};
        int B = 3, FULL = (1 << B) - 1, n = a.length;
        StringBuilder sb = new StringBuilder("a =");
        for (int x : a) sb.append(" ").append(x);
        System.out.println(sb + " (values below 2^" + B + ")");

        long brute = 0;                                   // O(N^2) reference
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if ((a[i] & a[j]) == 0) brute++;

        long[] f = new long[1 << B];                      // f[mask] starts as "how many values equal mask"
        int zeros = 0;
        for (int x : a) { f[x]++; if (x == 0) zeros++; }
        for (int bit = 0; bit < B; bit++)                 // one bit at a time: a prefix sum per dimension
            for (int mask = 0; mask <= FULL; mask++)
                if ((mask >> bit & 1) == 1) f[mask] += f[mask ^ (1 << bit)];
        // Now f[mask] = how many values are submasks of mask.

        long ordered = 0;
        for (int x : a) ordered += f[FULL ^ x];           // partners must fit inside the complement of x
        System.out.println("Ordered pairs, brute force: " + brute);
        System.out.println("Ordered pairs, SOS DP:      " + ordered);
        System.out.println("Unordered pairs i < j:      " + (ordered - zeros) / 2);
        // Time O(B * 2^B + N), space O(2^B)
    }
}

