public class Main {
    static int seed;
    static int next() { seed = (seed * 75 + 74) % 65537; return seed; }   // tiny repeatable random generator

    static int brute(int[] a) {                    // obviously correct: try every subarray, O(n^2)
        int best = a[0];
        for (int i = 0; i < a.length; i++) {
            int s = 0;
            for (int j = i; j < a.length; j++) { s += a[j]; best = Math.max(best, s); }
        }
        return best;
    }

    static int kadane(int[] a, boolean buggy) {    // fast DP, O(n); the buggy version starts best at 0
        int cur = 0, best = buggy ? 0 : a[0];
        for (int x : a) { cur = Math.max(x, cur + x); best = Math.max(best, cur); }
        return best;
    }

    static void stress(String name, boolean buggy) {
        seed = 1;                                  // fixed seed: the same cases on every run
        for (int t = 1; t <= 1000; t++) {
            int[] a = new int[next() % 6 + 1];     // tiny sizes and tiny values force ties and edge cases
            for (int i = 0; i < a.length; i++) a[i] = next() % 11 - 5;
            int want = brute(a), got = kadane(a, buggy);
            if (want != got) {
                StringBuilder sb = new StringBuilder();
                for (int x : a) sb.append(" ").append(x);
                System.out.println(name + ": case " + t + " FAILED, input =" + sb + ", expected " + want + ", got " + got);
                return;
            }
        }
        System.out.println(name + ": all 1000 random cases passed");
    }

    public static void main(String[] args) {
        System.out.println("Maximum subarray sum: fast DP compared with brute force");
        stress("correct version", false);
        stress("buggy version (best starts at 0)", true);
        // Each case: O(n^2) for the reference, O(n) for the fast version
    }
}

